pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strictly discourage dead space that is too small to hold any future
    // item in the observed 1..=100 stream.
    let min_usable = 1.0_f64;
    if (post_residual as f64) < min_usable {
        score += 1_000_000.0;
    } else {
        score += (post_residual as f64) * 10.0;
    }

    // Residual gaps below the next item are especially undesirable, while
    // preserving a moderate preference for tighter fits.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 250.0 * (next_item_size - post_residual) as f64;
    }

    // Opening an additional bin becomes more attractive as the number of
    // active bins grows, but only after existing bins have been used.
    let pressure = open_bins_count as f64 / (1.0 + (step_index as f64 + 1.0) / (total_items.max(1) as f64));
    score += 18.0 * pressure;

    // The empty-bin candidate should not win merely because it has zero
    // post-residual: charge it for the bin-opening pressure explicitly.
    if bin_residual == bin_capacity {
        score += 120.0 + 8.0 * pressure;
    }

    // If this is the sole fitting bin, favor using it strongly.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Tighten the preference toward bins whose residual is close to the
    // mean residual, while still rewarding low residual overall.
    if open_bins_count > 0 {
        score += 0.35 * (mean_residual - post_residual as f64).abs();
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let mut score = post_residual as f64;

    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let mean = mean_residual.max(0.0);

    // Prefer tight placements, while strongly avoiding gaps that are too
    // small to be useful for the arriving stream.
    let utilization = (capacity - residual) / capacity;
    score -= 16.0 * utilization;

    // Dead-space avoidance: a residual below the current item is especially
    // wasteful; smaller fragments are penalized progressively.
    let fragment = if post_residual < item_size {
        1.0 + (item_size - post_residual) as f64 / capacity
    } else {
        0.0
    };
    score += 34.0 * fragment;

    // Gaps below the lookahead size are likely to become stranded, but do
    // not over-penalize a gap that can still hold the current item.
    if next_item_size > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64 / capacity;
        score += 10.0 * shortfall;
    }

    // A gap below a nominal useful minimum is a poor placement candidate.
    if post_residual < 10 {
        score += 4.0 * (10.0 - post_residual as f64);
    }

    // With many open bins, preserve bins whose remaining capacity is
    // valuable for larger future arrivals rather than accepting poor fits.
    let pressure = (open_bins_count as f64).sqrt();
    score += 0.18 * pressure * mean;
    if mean > 0.0 && residual > mean {
        score += 0.12 * pressure * (residual - mean) / capacity;
    }

    // If this is the last fitting bin, opening another bin is comparatively
    // attractive; make the existing-bin candidate less attractive.
    if fitting_bins_count == 1 {
        score += 8.0;
    }

    // Near the end of the stream, prioritize immediate packing and reduce
    // the value of preserving future flexibility.
    let progress = if total_items == 0 {
        1.0
    } else {
        step_index as f64 / total_items as f64
    };
    score *= 0.75 + 0.25 * (1.0 - progress);

    // Empty-bin candidates receive a mild opening bias when the current
    // item is large or existing residuals are generally fragmented.
    if bin_residual == bin_capacity {
        score += 3.0;
        if item > capacity * 0.5 {
            score -= 2.0;
        }
    }

    score
}

