pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    let is_new_bin = bin_residual >= bin_capacity;
    let fills_bin = post <= 0.5 || item >= capacity - 0.5;
    let exact_capacity_multiple = bin_capacity > 0 && item_size > 0 && item_size % (bin_capacity / 4).max(1) == 0;

    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    let mean = mean_residual.clamp(0.0, capacity);
    let scarcity = (mean - post).max(0.0);
    let concentration = post * post / capacity;
    let fragmentation = (post % 25) as f64;
    let next_mod = if next_item_size > 0 {
        (next_item_size % 20) as f64
    } else {
        0.0
    };

    score += 0.035 * concentration;
    score += 0.018 * fragmentation;
    score -= 0.028 * scarcity;
    score -= 0.012 * progress.min(1.0);

    if exact_capacity_multiple {
        score -= 8.0;
    }

    if fills_bin {
        score -= 30.0;
    }

    if next_item_size > 0 && post >= next_item_size as f64 {
        let next_fit_bonus = 1.0 - (post - next) / capacity.max(1.0);
        score -= 16.0 * next_fit_bonus;
    } else if next_item_size > 0 {
        let blocked = (next - post).max(0.0);
        score += 0.045 * blocked;
    }

    if next_item_size > 0 {
        let post_class = (post as u32 % 10) as f64;
        let next_class = (next_item_size % 10) as f64;
        let harmonic_gap = (post_class - next_class).abs();
        score += 0.11 * harmonic_gap;
        score -= 0.08 * next_mod;
    }

    if is_new_bin {
        score += 14.0 + 0.08 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 6.0;
        }
    } else {
        if fitting_bins_count == 1 {
            score -= 4.0;
        }
        if post < item.min(next_item_size.max(1)) as f64 {
            score += 10.0;
        }
    }

    if open_bins_count == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (10.0 - post_residual as f64) * 3.0;
    }

    if post_residual == 0 {
        score -= 18.0;
    }

    let pressure = if total_items > 0 {
        open_bins_count as f64 / total_items as f64
    } else {
        0.0
    };
    score += pressure * 20.0;

    let utilization = if bin_capacity > 0 {
        (bin_capacity - bin_residual) as f64 / bin_capacity as f64
    } else {
        0.0
    };
    score -= utilization * 8.0;

    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score += 30.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 12.0;
    }

    let deviation = mean_residual - post_residual as f64;
    score += deviation * 0.35;

    let progression = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= progression * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Small leftover gaps are usually difficult to reuse and are penalized
    // strongly. Exact fits are strongly preferred.
    let unusable_gap = if post_residual < item_size {
        post_residual as f64
    } else {
        0.0
    };
    score += unusable_gap * 9.0;

    // A residual that cannot accommodate even the smallest plausible future item
    // is dead space; the next-item lookahead identifies especially costly gaps.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // Exact completion is ideal, but slight slack is still preferable to
    // opening another bin.
    if post_residual == 0 {
        score -= 35.0;
    }

    // Pressure from many open bins favors concentrating items into fewer bins.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * 0.65;

    // Relative residual imbalance discourages creating an outlier bin when
    // other bins are substantially tighter.
    let residual_excess = (post_residual as f64 - mean_residual).max(0.0);
    score += residual_excess * 0.045;

    // If this is the only fitting bin, it has urgency; otherwise, avoid
    // consuming a bin that could be saved for a more restrictive future item.
    if fitting_bins_count <= 1 {
        score -= 18.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0).min(8.0) * 0.35;
    }

    // Near the end of the stream, orphan gaps are less valuable and exact
    // closure becomes more attractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + progress * 0.18;

    // A new bin is a last resort unless all open bins are badly constrained.
    if bin_residual == bin_capacity {
        score += 28.0;
        if open_bins_count > 0 {
            score += open_bins_count as f64 * 0.55;
        }
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}
